  insert into public.categorias (restaurante_id, nombre, orden, traducciones, estacion) values (rid, 'Entradas', 0, '{"en": {"nombre": "Starters"}, "pt": {"nombre": "Entradas"}, "fr": {"nombre": "Entrées"}, "de": {"nombre": "Vorspeisen"}, "it": {"nombre": "Antipasti"}, "zh": {"nombre": "前菜"}, "nl": {"nombre": "Voorgerechten"}}'::jsonb, 'Cocina') returning id into cid;
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Carpaccio de filete de res', 'Finas láminas de filete de res con alcaparras, rúcula y queso parmesano.', 12000, '{}', 0, false, '{"en": {"descripcion": "Thin slices of beef tenderloin with capers, arugula and Parmesan cheese."}, "pt": {"descripcion": "Finas lâminas de filé bovino com alcaparras, rúcula e queijo parmesão."}, "fr": {"descripcion": "Fines lamelles de filet de bœuf, câpres, roquette et parmesan."}, "de": {"descripcion": "Hauchdünne Rinderfiletscheiben mit Kapern, Rucola und Parmesan."}, "it": {"descripcion": "Sottili fette di filetto di manzo con capperi, rucola e parmigiano."}, "zh": {"descripcion": "薄切牛里脊，配刺山柑、芝麻菜和帕玛森奶酪。"}, "nl": {"descripcion": "Dunne plakjes ossenhaas met kappertjes, rucola en Parmezaanse kaas."}}'::jsonb, '[]'::jsonb, 'vacuno');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Carpaccio de salmón', 'Finas láminas de filete de salmón con alcaparras, rúcula y queso parmesano.', 12000, '{}', 1, false, '{"en": {"descripcion": "Thin slices of salmon fillet with capers, arugula and Parmesan cheese."}, "pt": {"descripcion": "Finas lâminas de filé de salmão com alcaparras, rúcula e queijo parmesão."}, "fr": {"descripcion": "Fines lamelles de saumon, câpres, roquette et parmesan."}, "de": {"descripcion": "Hauchdünne Lachsfiletscheiben mit Kapern, Rucola und Parmesan."}, "it": {"descripcion": "Sottili fette di filetto di salmone con capperi, rucola e parmigiano."}, "zh": {"descripcion": "薄切三文鱼，配刺山柑、芝麻菜和帕玛森奶酪。"}, "nl": {"descripcion": "Dunne plakjes zalmfilet met kappertjes, rucola en Parmezaanse kaas."}}'::jsonb, '[]'::jsonb, 'pescado');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Arancini con salsa de carne o queso mozzarella', 'Bolitas de arroz apanadas y rellenas con ragú sobre salsa pomodoro o mozzarella sobre bechamel.', 11000, '{}', 2, false, '{"en": {"descripcion": "Breaded rice balls filled with meat ragù on tomato sauce, or with mozzarella on béchamel."}, "pt": {"descripcion": "Bolinhos de arroz empanados recheados com ragu sobre molho de tomate, ou mozzarella sobre bechamel."}, "fr": {"descripcion": "Boulettes de riz panées farcies au ragù sur sauce tomate, ou à la mozzarella sur béchamel."}, "de": {"descripcion": "Panierte Reisbällchen mit Ragù auf Tomatensauce oder mit Mozzarella auf Béchamel."}, "it": {"descripcion": "Arancini impanati ripieni di ragù su salsa al pomodoro, o di mozzarella su besciamella."}, "zh": {"descripcion": "裹粉炸饭团，内馅为肉酱配番茄酱，或马苏里拉奶酪配白酱。"}, "nl": {"descripcion": "Gepaneerde rijstballetjes gevuld met ragù op tomatensaus, of met mozzarella op bechamel."}}'::jsonb, '[{"nombre": "Relleno", "min": 1, "max": 1, "valores": [{"nombre": "Ragú de carne sobre salsa pomodoro", "precio": 0}, {"nombre": "Mozzarella sobre bechamel", "precio": 0}]}]'::jsonb, 'arroz');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Ensalada caprese', 'Variedad de tomates frescos y de temporada con queso mozzarella y albahaca fresca.', 9000, '{"vegetariano"}', 3, false, '{"en": {"descripcion": "Fresh seasonal tomatoes with mozzarella and fresh basil."}, "pt": {"descripcion": "Variedade de tomates frescos da estação com mozzarella e manjericão fresco."}, "fr": {"descripcion": "Tomates fraîches de saison, mozzarella et basilic frais."}, "de": {"descripcion": "Frische Saisontomaten mit Mozzarella und frischem Basilikum."}, "it": {"descripcion": "Pomodori freschi di stagione con mozzarella e basilico fresco."}, "zh": {"descripcion": "时令新鲜番茄配马苏里拉奶酪和新鲜罗勒。"}, "nl": {"descripcion": "Verse seizoenstomaten met mozzarella en verse basilicum."}}'::jsonb, '[]'::jsonb, 'tomate');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Berenjenas parmesana', 'Berenjenas en láminas grilladas con pomodoro, mozzarella y gratinadas al horno.', 9000, '{}', 4, false, '{"en": {"descripcion": "Grilled eggplant slices with tomato sauce and mozzarella, baked au gratin."}, "pt": {"descripcion": "Berinjelas em lâminas grelhadas com molho de tomate e mozzarella, gratinadas no forno."}, "fr": {"descripcion": "Aubergines grillées en tranches, sauce tomate et mozzarella, gratinées au four."}, "de": {"descripcion": "Gegrillte Auberginenscheiben mit Tomatensauce und Mozzarella, im Ofen überbacken."}, "it": {"descripcion": "Melanzane grigliate a fette con pomodoro e mozzarella, gratinate al forno."}, "zh": {"descripcion": "烤茄子片配番茄酱和马苏里拉奶酪，焗烤而成。"}, "nl": {"descripcion": "Gegrilde plakken aubergine met tomatensaus en mozzarella, gegratineerd in de oven."}}'::jsonb, '[]'::jsonb, 'berenjena');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Tabla de antipasti (para compartir)', 'Embutidos, quesos, berenjena y setas grilladas.', 18000, '{}', 5, true, '{"en": {"descripcion": "Cured meats, cheeses, eggplant and grilled mushrooms. To share."}, "pt": {"descripcion": "Embutidos, queijos, berinjela e cogumelos grelhados. Para compartilhar."}, "fr": {"descripcion": "Charcuterie, fromages, aubergine et champignons grillés. À partager."}, "de": {"descripcion": "Wurstwaren, Käse, Aubergine und gegrillte Pilze. Zum Teilen."}, "it": {"descripcion": "Salumi, formaggi, melanzane e funghi grigliati. Da condividere."}, "zh": {"descripcion": "冷切肉、奶酪、茄子和烤蘑菇，适合分享。"}, "nl": {"descripcion": "Vleeswaren, kazen, aubergine en gegrilde paddenstoelen. Om te delen."}}'::jsonb, '[]'::jsonb, 'queso');
  insert into public.categorias (restaurante_id, nombre, orden, traducciones, estacion) values (rid, 'Platos principales', 1, '{"en": {"nombre": "Main courses"}, "pt": {"nombre": "Pratos principais"}, "fr": {"nombre": "Plats principaux"}, "de": {"nombre": "Hauptgerichte"}, "it": {"nombre": "Piatti principali"}, "zh": {"nombre": "主菜"}, "nl": {"nombre": "Hoofdgerechten"}}'::jsonb, 'Cocina') returning id into cid;
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Tagliata di manzo, fettuccine y verduras', 'Lomo de res, grillada de vegetales y fettuccine fresco.', 18500, '{}', 0, false, '{"en": {"descripcion": "Beef loin with grilled vegetables and fresh fettuccine."}, "pt": {"descripcion": "Lombo bovino com legumes grelhados e fettuccine fresco."}, "fr": {"descripcion": "Faux-filet de bœuf, légumes grillés et fettuccine fraîches."}, "de": {"descripcion": "Rinderlende mit gegrilltem Gemüse und frischen Fettuccine."}, "it": {"descripcion": "Lombata di manzo con verdure grigliate e fettuccine fresche."}, "zh": {"descripcion": "牛里脊配烤蔬菜和新鲜宽面。"}, "nl": {"descripcion": "Runderlende met gegrilde groenten en verse fettuccine."}}'::jsonb, '[]'::jsonb, 'vacuno');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Tricornio negro de sepia relleno de salmón ahumado con crema de caperunes', 'Pasta fresca rellena de salmón y trucha ahumada, con crema de alcaparras y chalotes y palta asada.', 16500, '{}', 1, true, '{"en": {"descripcion": "Fresh squid-ink pasta filled with smoked salmon and trout, with caper and shallot cream and roasted avocado."}, "pt": {"descripcion": "Massa fresca com tinta de lula recheada de salmão e truta defumados, com creme de alcaparras e chalotas e abacate assado."}, "fr": {"descripcion": "Pâtes fraîches à l’encre de seiche farcies au saumon et à la truite fumés, crème de câpres et échalotes, avocat rôti."}, "de": {"descripcion": "Frische Sepia-Pasta mit Füllung aus geräuchertem Lachs und Forelle, Kapern-Schalotten-Creme und gerösteter Avocado."}, "it": {"descripcion": "Pasta fresca al nero di seppia ripiena di salmone e trota affumicati, con crema di capperi e scalogni e avocado arrosto."}, "zh": {"descripcion": "墨鱼汁鲜意面，内馅为烟熏三文鱼和鳟鱼，配刺山柑红葱奶油酱和烤牛油果。"}, "nl": {"descripcion": "Verse inktvispasta gevuld met gerookte zalm en forel, met kappertjes-sjalottenroom en geroosterde avocado."}}'::jsonb, '[]'::jsonb, 'pasta');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Fettuccine al sapore di mare', 'Fettuccine fresco con mariscos.', 16500, '{}', 2, true, '{"en": {"descripcion": "Fresh fettuccine with seafood."}, "pt": {"descripcion": "Fettuccine fresco com frutos do mar."}, "fr": {"descripcion": "Fettuccine fraîches aux fruits de mer."}, "de": {"descripcion": "Frische Fettuccine mit Meeresfrüchten."}, "it": {"descripcion": "Fettuccine fresche ai frutti di mare."}, "zh": {"descripcion": "新鲜宽面配海鲜。"}, "nl": {"descripcion": "Verse fettuccine met zeevruchten."}}'::jsonb, '[]'::jsonb, 'camaron');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Agnolotti de pasta fresca rellenos de cola de buey braseada', 'Pasta fresca enrollada rellena de rabo de toro estofado y desmenuzado sobre salsa casera de tomate y setas porcini.', 17000, '{}', 3, false, '{"en": {"descripcion": "Fresh pasta filled with braised, shredded oxtail on homemade tomato and porcini sauce."}, "pt": {"descripcion": "Massa fresca recheada de rabada estufada e desfiada sobre molho caseiro de tomate e cogumelos porcini."}, "fr": {"descripcion": "Pâtes fraîches farcies de queue de bœuf braisée et effilochée, sauce maison tomate et cèpes."}, "de": {"descripcion": "Frische Pasta gefüllt mit geschmortem, gezupftem Ochsenschwanz auf hausgemachter Tomaten-Steinpilz-Sauce."}, "it": {"descripcion": "Pasta fresca ripiena di coda di bue brasata e sfilacciata su salsa casalinga di pomodoro e porcini."}, "zh": {"descripcion": "鲜意面包裹炖牛尾丝，配自制番茄牛肝菌酱。"}, "nl": {"descripcion": "Verse pasta gevuld met gestoofde, getrokken ossenstaart op huisgemaakte tomaten-eekhoorntjesbroodsaus."}}'::jsonb, '[]'::jsonb, 'pasta');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Tortelloni de pierna de cerdo ahumada y gorgonzola', 'Tortelloni de pasta fresca rellenos con pierna de cerdo ahumada y desmenuzada con gorgonzola sobre crema de guanciale.', 17000, '{}', 4, false, '{"en": {"descripcion": "Fresh tortelloni filled with smoked pulled pork leg and gorgonzola on guanciale cream."}, "pt": {"descripcion": "Tortelloni de massa fresca recheados com pernil suíno defumado desfiado e gorgonzola sobre creme de guanciale."}, "fr": {"descripcion": "Tortelloni frais farcis de jambon de porc fumé effiloché et gorgonzola, crème de guanciale."}, "de": {"descripcion": "Frische Tortelloni mit geräucherter, gezupfter Schweinekeule und Gorgonzola auf Guanciale-Creme."}, "it": {"descripcion": "Tortelloni di pasta fresca ripieni di coscia di maiale affumicata sfilacciata e gorgonzola su crema di guanciale."}, "zh": {"descripcion": "鲜意大利大馄饨，内馅为烟熏猪腿肉丝和戈贡佐拉奶酪，配猪颊肉奶油酱。"}, "nl": {"descripcion": "Verse tortelloni gevuld met gerookte, getrokken varkensbout en gorgonzola op guanciale-room."}}'::jsonb, '[]'::jsonb, 'cerdo');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Gnocchi cacciatore', 'Gnocchi de papas acompañados de salsa de tomate, setas, hierbas y aceitunas.', 15000, '{}', 5, false, '{"en": {"descripcion": "Potato gnocchi with tomato sauce, mushrooms, herbs and olives."}, "pt": {"descripcion": "Nhoque de batata com molho de tomate, cogumelos, ervas e azeitonas."}, "fr": {"descripcion": "Gnocchis de pommes de terre, sauce tomate, champignons, herbes et olives."}, "de": {"descripcion": "Kartoffelgnocchi mit Tomatensauce, Pilzen, Kräutern und Oliven."}, "it": {"descripcion": "Gnocchi di patate con salsa di pomodoro, funghi, erbe e olive."}, "zh": {"descripcion": "土豆团子配番茄酱、蘑菇、香草和橄榄。"}, "nl": {"descripcion": "Aardappelgnocchi met tomatensaus, paddenstoelen, kruiden en olijven."}}'::jsonb, '[]'::jsonb, 'pasta');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Risotto con langostinos patagónicos', 'Cremoso risotto con semillas de hinojo y langostinos patagónicos grillados.', 16500, '{}', 6, false, '{"en": {"descripcion": "Creamy risotto with fennel seeds and grilled Patagonian prawns."}, "pt": {"descripcion": "Risoto cremoso com sementes de erva-doce e lagostins patagônicos grelhados."}, "fr": {"descripcion": "Risotto crémeux aux graines de fenouil et langoustines de Patagonie grillées."}, "de": {"descripcion": "Cremiges Risotto mit Fenchelsamen und gegrillten patagonischen Garnelen."}, "it": {"descripcion": "Risotto cremoso ai semi di finocchio con gamberi patagonici alla griglia."}, "zh": {"descripcion": "茴香籽奶油烩饭配烤巴塔哥尼亚大虾。"}, "nl": {"descripcion": "Romige risotto met venkelzaad en gegrilde Patagonische garnalen."}}'::jsonb, '[]'::jsonb, 'langostino');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Ravioles de zapallo camote asado, nueces y ricotta sobre mantequilla al romero', 'Zapallo camote asado al horno acompañado de nueces y ricotta de la casa sobre una cremosa mantequilla de salvia fresca.', 16500, '{"vegetariano"}', 7, false, '{"en": {"descripcion": "Oven-roasted butternut squash ravioli with walnuts and house ricotta on a creamy fresh sage butter."}, "pt": {"descripcion": "Ravióis de abóbora assada no forno com nozes e ricota da casa sobre manteiga cremosa de sálvia fresca."}, "fr": {"descripcion": "Raviolis de courge rôtie au four, noix et ricotta maison sur un beurre crémeux à la sauge fraîche."}, "de": {"descripcion": "Ravioli mit ofengerösteter Butternuss, Walnüssen und hausgemachtem Ricotta auf cremiger Salbeibutter."}, "it": {"descripcion": "Ravioli di zucca arrosto al forno con noci e ricotta della casa su burro cremoso alla salvia fresca."}, "zh": {"descripcion": "烤南瓜意式饺子，配核桃和自制乳清奶酪，淋鼠尾草黄油。"}, "nl": {"descripcion": "Ravioli van in de oven geroosterde flespompoen met walnoten en huisgemaakte ricotta op romige salieboter."}}'::jsonb, '[]'::jsonb, 'camote');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Spaghetti al pesto', 'Pasta fresca con salsa al pesto de albahacas frescas.', 13500, '{"vegetariano"}', 8, false, '{"en": {"descripcion": "Fresh pasta with fresh basil pesto."}, "pt": {"descripcion": "Massa fresca com molho pesto de manjericão fresco."}, "fr": {"descripcion": "Pâtes fraîches au pesto de basilic frais."}, "de": {"descripcion": "Frische Pasta mit Pesto aus frischem Basilikum."}, "it": {"descripcion": "Pasta fresca al pesto di basilico fresco."}, "zh": {"descripcion": "新鲜意面配新鲜罗勒青酱。"}, "nl": {"descripcion": "Verse pasta met pesto van verse basilicum."}}'::jsonb, '[]'::jsonb, 'fideos');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Lasaña tradicional al ragú', 'Pasta fresca con salsa al ragú.', 16000, '{}', 9, false, '{"en": {"descripcion": "Fresh pasta with ragù sauce."}, "pt": {"descripcion": "Massa fresca com molho ragu."}, "fr": {"descripcion": "Pâtes fraîches à la sauce ragù."}, "de": {"descripcion": "Frische Pasta mit Ragù-Sauce."}, "it": {"descripcion": "Pasta fresca al ragù."}, "zh": {"descripcion": "新鲜意面配肉酱。"}, "nl": {"descripcion": "Verse pasta met ragùsaus."}}'::jsonb, '[]'::jsonb, 'pasta');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Spaghetti para nuestros niños (hasta 10 años)', 'Pasta fresca con salsa al ragú, pesto o mantequilla a elegir.', 8000, '{}', 10, false, '{"en": {"descripcion": "Fresh pasta with your choice of ragù, pesto or butter. For kids up to 10."}, "pt": {"descripcion": "Massa fresca com molho ragu, pesto ou manteiga, à escolha. Para crianças até 10 anos."}, "fr": {"descripcion": "Pâtes fraîches sauce ragù, pesto ou beurre au choix. Pour les enfants jusqu’à 10 ans."}, "de": {"descripcion": "Frische Pasta mit Ragù, Pesto oder Butter nach Wahl. Für Kinder bis 10 Jahre."}, "it": {"descripcion": "Pasta fresca con ragù, pesto o burro a scelta. Per bambini fino a 10 anni."}, "zh": {"descripcion": "新鲜意面，可选肉酱、青酱或黄油。适合10岁以下儿童。"}, "nl": {"descripcion": "Verse pasta met naar keuze ragù, pesto of boter. Voor kinderen tot 10 jaar."}}'::jsonb, '[{"nombre": "Salsa", "min": 1, "max": 1, "valores": [{"nombre": "Ragú", "precio": 0}, {"nombre": "Pesto", "precio": 0}, {"nombre": "Mantequilla", "precio": 0}]}]'::jsonb, 'fideos');
  insert into public.categorias (restaurante_id, nombre, orden, traducciones, estacion) values (rid, 'Postres', 2, '{"en": {"nombre": "Desserts"}, "pt": {"nombre": "Sobremesas"}, "fr": {"nombre": "Desserts"}, "de": {"nombre": "Desserts"}, "it": {"nombre": "Dolci"}, "zh": {"nombre": "甜点"}, "nl": {"nombre": "Desserts"}}'::jsonb, 'Cocina') returning id into cid;
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Cannoli relleno de crema de limón', 'Suave masa dulce y frita rellena con una crema de limón sobre ragú de frutos rojos de estación.', 6500, '{}', 0, false, '{"en": {"descripcion": "Soft, sweet fried pastry filled with lemon cream on a seasonal berry ragù."}, "pt": {"descripcion": "Massa doce e frita recheada com creme de limão sobre ragu de frutas vermelhas da estação."}, "fr": {"descripcion": "Pâte sucrée et frite garnie de crème au citron sur un ragoût de fruits rouges de saison."}, "de": {"descripcion": "Zarter, frittierter Teig mit Zitronencreme auf einem Ragout aus saisonalen Beeren."}, "it": {"descripcion": "Cannolo fritto ripieno di crema al limone su ragù di frutti rossi di stagione."}, "zh": {"descripcion": "酥炸甜卷，内馅柠檬奶油，配时令莓果酱。"}, "nl": {"descripcion": "Zacht gefrituurd deeg gevuld met citroenroom op een ragout van seizoensbessen."}}'::jsonb, '[]'::jsonb, 'dulces');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Tiramisú', 'Tradicional postre de crema de queso y suaves bizcochos remojados en café y amaretti.', 5500, '{}', 1, true, '{"en": {"descripcion": "Traditional dessert of cream cheese and soft sponge fingers soaked in coffee and amaretti."}, "pt": {"descripcion": "Sobremesa tradicional de creme de queijo e biscoitos macios embebidos em café e amaretti."}, "fr": {"descripcion": "Dessert traditionnel à la crème de fromage et biscuits moelleux imbibés de café et d’amaretti."}, "de": {"descripcion": "Klassisches Dessert aus Käsecreme und zarten, in Kaffee und Amaretti getränkten Biskuits."}, "it": {"descripcion": "Dolce tradizionale con crema al formaggio e savoiardi bagnati nel caffè e amaretti."}, "zh": {"descripcion": "传统提拉米苏：奶酪奶油配浸咖啡和杏仁饼的手指饼干。"}, "nl": {"descripcion": "Traditioneel dessert van kaasroom en zachte lange vingers gedrenkt in koffie en amaretti."}}'::jsonb, '[]'::jsonb, 'torta');
