-- Carta de demostración "Pastalegre · Trattoria en Valparaíso" (Hotel Palacio Astoreca, Montealegre 149, Cerro Alegre),
-- para mostrársela al restaurante. Hecha con su carta real de pastalegre.com/menu (12-11-2026), con sus precios exactos:
-- 5 categorías, 46 platos y vinos. Nombres de platos en español; descripciones traducidas a inglés, portugués,
-- francés, alemán, italiano, chino y holandés. Los 3 platos que su web marca "Végétarien" van con la etiqueta "vegetariano"
-- y los vinos "Recomendado" con la etiqueta "recomendado". Logo: public/demo/pastalegre/logo.png.
-- Reservas como en su web (Salón y Terraza, cada 30 min): almuerzo martes a domingo 13:00-16:30; cena viernes y sábado
-- 19:00-21:00 (su web dice que abren hasta las 21:30). Requiere la migración 0034.
-- Se puede ejecutar más de una vez: borra y vuelve a crear la carta de la demo (categorías y platos), sin tocar nada más.

do $$
declare
  rid uuid;
  cid uuid;
begin
  select id into rid from public.restaurantes where slug = 'pastalegre';
  if rid is null then
  end if;
  update public.restaurantes set
    nombre = 'Pastalegre',
    descripcion = 'Trattoria de pasta fresca y cocina auténtica italiana · Hotel Palacio Astoreca, Montealegre 149, Cerro Alegre, Valparaíso',
    logo_url = '/demo/pastalegre/logo.png',
    tema = 'forno',
    color_primario = '#d90f35',
    color_fondo = '#fbf3ee',
    moneda = 'CLP',
    plan = 'pro',
    idiomas = array['en', 'pt', 'fr', 'de', 'it', 'zh', 'nl'],
    traducciones = '{"en": {"descripcion": "Fresh pasta and authentic Italian cooking · Hotel Palacio Astoreca, Montealegre 149, Cerro Alegre, Valparaíso"}, "pt": {"descripcion": "Massa fresca e autêntica cozinha italiana · Hotel Palacio Astoreca, Montealegre 149, Cerro Alegre, Valparaíso"}, "fr": {"descripcion": "Pâtes fraîches et authentique cuisine italienne · Hôtel Palacio Astoreca, Montealegre 149, Cerro Alegre, Valparaíso"}, "de": {"descripcion": "Frische Pasta und authentische italienische Küche · Hotel Palacio Astoreca, Montealegre 149, Cerro Alegre, Valparaíso"}, "it": {"descripcion": "Pasta fresca e autentica cucina italiana · Hotel Palacio Astoreca, Montealegre 149, Cerro Alegre, Valparaíso"}, "zh": {"descripcion": "新鲜手工意面与地道意大利菜 · Palacio Astoreca 酒店，Montealegre 149，Cerro Alegre，瓦尔帕莱索"}, "nl": {"descripcion": "Verse pasta en authentieke Italiaanse keuken · Hotel Palacio Astoreca, Montealegre 149, Cerro Alegre, Valparaíso"}}'::jsonb,
    ajustes = ajustes || '{"pais": "CL", "zona_horaria": "America/Santiago", "imagenes_defecto": true, "redes": {"instagram": "https://www.instagram.com/pastalegre/", "web": "https://www.pastalegre.com"}, "estaciones": ["Cocina", "Barra"], "modulos": {"reservas": true}, "reservas": {"online": true, "tolerancia": 15, "mostrar_tolerancia": true, "recordatorio": true, "horas_antes": 3, "ninos": true, "correo": "obligatorio", "ubicaciones": ["Salón", "Terraza"], "turnos": [{"nombre": "Almuerzo", "desde": "13:00", "hasta": "16:30", "cada": 30, "dias": [0, 2, 3, 4, 5, 6], "cupo": 0}, {"nombre": "Cena", "desde": "19:00", "hasta": "21:00", "cada": 30, "dias": [5, 6], "cupo": 0}]}}'::jsonb
  where id = rid;

  delete from public.platos where restaurante_id = rid;
  delete from public.categorias where restaurante_id = rid;
end $$;
